Close <https://github.com/vim-denops/denops.vim/issues/48|vim-denops/denops.vim#48> by providing `once` callback.

```
test({
  mode: "all",
  name: "register() registers named callback",
  fn: async(denops) =&gt; {
    const name = register(denops, () =&gt; Promise.resolve("Hello"), {
      name: "test:named",
    });
    assertEquals(name, "test:named");
    assertEquals(await denops.dispatch(denops.name, name), "Hello");
    assertEquals(await denops.dispatch(denops.name, name), "Hello");
  },
});

test({
  mode: "all",
  name: "register() registers named once callback",
  fn: async(denops) =&gt; {
    const name = register(denops, () =&gt; Promise.resolve("Hello"), {
      name: "test:named:once",
      once: true,
    });
    assertEquals(name, "test:named:once");
    assertEquals(await denops.dispatch(denops.name, name), "Hello");

    // The method will be removed
    await assertThrowsAsync(async () =&gt; {
      await denops.dispatch(denops.name, name);
    }, undefined, `No method '${name}' exists`);
  },
});


test({
  mode: "all",
  name: "register() registers anonymous callback",
  fn: async(denops) =&gt; {
    const name = register(denops, () =&gt; Promise.resolve("Hello"));
    assertEquals(await denops.dispatch(denops.name, name), "Hello");
    assertEquals(await denops.dispatch(denops.name, name), "Hello");
  },
});

test({
  mode: "all",
  name: "register() registers anonymous once callback",
  fn: async(denops) =&gt; {
    const name = register(denops, () =&gt; Promise.resolve("Hello"), {
      once: true,
    });
    assertEquals(await denops.dispatch(denops.name, name), "Hello");

    // The method will be removed
    await assertThrowsAsync(async () =&gt; {
      await denops.dispatch(denops.name, name);
    }, undefined, `No method '${name}' exists`);
  },
});
```
